import sys

def transform_debug(grid):
    h, w = len(grid), len(grid[0])

    # Find dot
    dot_pos = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 9:
                dot_pos = (r, c)
                break
        if dot_pos:
            break

    if not dot_pos:
        return [row[:] for row in grid]

    dot_r, dot_c = dot_pos
    center_r, center_c = dot_r + 1, dot_c + 1
    if center_r < 0 or center_r >= h or center_c < 0 or center_c >= w:
        center_r, center_c = dot_r, dot_c

    output = [row[:] for row in grid]

    # Cross drawing - debug row 5
    for r in range(h):
        for c in range(w):
            if (r, c) == (center_r, center_c):
                continue
            if grid[r][c] != 0:
                continue

            dr, dc = r - center_r, c - center_c

            # Debug specifically for row 5
            if r == 5:
                print(f"\nCell (5,{c}): dr={dr}, dc={dc}, abs(dr)={abs(dr)}, abs(dc)={abs(dc)}")

            # Cross conditions
            if dc == 0 and 1 <= abs(dr) <= 3:
                output[r][c] = 1
            elif r == center_r and abs(dc) == 1:
                output[r][c] = 1
            elif abs(dr) == 1 and abs(dc) <= 1:
                output[r][c] = 1

    return output

